declare(strict_types=1);
require_once dirname(__DIR__).'/private/app/FinancialReview.php';
require_once dirname(__DIR__).'/private/app/FinanceMonitoring.php';
ini_set('display_errors','0');ini_set('session.use_strict_mode','1');ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Lax');ini_set('session.cookie_secure',(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'1':'0');session_name('IPDAMSSESSID');session_start();
header('Cache-Control: no-store, private');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: SAMEORIGIN');header('Referrer-Policy: no-referrer');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'self'; form-action 'self'");
function fre(mixed $v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function frhidden(int $org,int $bank,string $period,int $version=0):void{foreach(['organization_id'=>$org,'bank_account_id'=>$bank,'period'=>$period,'expected_version'=>$version] as $k=>$v)echo '<input type="hidden" name="'.fre($k).'" value="'.fre($v).'">';}
$data=null;$error='';$snapshot=null;$banks=[];$checks=[];$writable=false;$period=(string)($_GET['period']??date('Y-m'));
try{
 demand(($_SERVER['REQUEST_METHOD']??'GET')==='GET','Read-only page; use authenticated API for actions',405);$db=database();$user=currentUser($db);$org=idOf($_GET,'organization_id');$service=new FinancialReview($db,$user);$data=$service->read($_GET);$bank=idOf($_GET,'bank_account_id');
 $banks=q($db,'SELECT id,bank_name,account_label FROM bank_accounts WHERE organization_id=? ORDER BY id',[$org])->fetchAll();$organization=FinanceAccess::read($db,$user,$org);
 $writable=$user['role']==='SUPER_ADMIN'||($user['role']===$organization['kind']&&in_array($organization['kind'],['SCHOOL','DIVISION'],true));
 if(!empty($_GET['snapshot_id']))$snapshot=$service->snapshot($_GET);
 $end=(new DateTimeImmutable($period.'-01'))->format('Y-m-t');
 $all=q($db,'SELECT c.*,d.display_number AS dv_number FROM checks c JOIN disbursement_vouchers d ON d.id=c.dv_id AND d.organization_id=c.organization_id WHERE c.organization_id=? AND c.bank_account_id=? AND c.created_at<? ORDER BY c.id LIMIT 5001',[$org,$bank,(new DateTimeImmutable($end))->modify('+1 day')->format('Y-m-d').' 00:00:00'])->fetchAll();demand(count($all)<=5000,'Narrow account check history',409);
 $events=q($db,'SELECT e.* FROM payment_events e JOIN checks c ON c.id=e.check_id WHERE c.organization_id=? AND c.bank_account_id=? ORDER BY e.created_at,e.id LIMIT 10001',[$org,$bank])->fetchAll();demand(count($events)<=10000,'Account payment history exceeds workpaper capacity',409);
 foreach($all as $c){$c['stage_at_end']=CashFundReports::stageAt($c,$events,$end);if(!in_array($c['stage_at_end'],['CLEARED','CANCELLED','REPLACED'],true))$checks[]=$c;}
}catch(DomainError $e){http_response_code($e->status);$error=$e->getMessage();}catch(Throwable $e){http_response_code(500);error_log('Financial review: '.$e->getMessage());$error='Financial review unavailable; no financial records were posted.';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IPDAMS · Bank reconciliation and historical reports</title><link rel="stylesheet" href="../assets/cash-fund-reports.css"><script src="../assets/financial-review.js" defer></script></head><body class="finance-review">
<header class="toolbar noprint"><div><div class="eyebrow">IPDAMS / CASH &amp; BANK</div><h1>Bank reconciliation &amp; historical reports</h1><p>Account-wide verified sources, preserved revisions and immutable report evidence.</p></div><button type="button" data-finance-print>Print workpaper</button></header>
<?php if($error):?><p class="alert" role="alert"><?=fre($error)?></p><?php else:$draft=$data['draft'];$version=(int)$data['version_id'];$opening=$data['opening']??null;$isClosed=($draft['status']??'')==='CLOSED';$legacyClosed=!$draft&&($data['legacy']['status']??'')==='CLOSED';$csrf=(string)($_SESSION['csrf']??'');$selectedSources=array_column($draft['lines']??[],'source_id');$selectedChecks=array_column($draft['lines']??[],'check_id');?>
<form method="get" class="filters noprint"><input type="hidden" name="organization_id" value="<?=fre($org)?>"><label>Account<select name="bank_account_id"><?php foreach($banks as $b):?><option value="<?=fre($b['id'])?>" <?=(int)$b['id']===$bank?'selected':''?>><?=fre($b['bank_name'].' / '.$b['account_label'])?></option><?php endforeach;?></select></label><label>Month<input type="month" name="period" value="<?=fre($period)?>" required></label><label>Snapshot version<input type="number" min="1" name="snapshot_id" value="<?=fre($_GET['snapshot_id']??'')?>"></label><button>Load workpaper</button></form>
<nav class="report-tabs noprint"><a href="#reconciliation">Reconciliation</a><a href="#verified-sources">Verified sources</a><a href="#snapshots">Historical reports</a><a href="finance-monitor.php?organization_id=<?=fre($org)?>">Download utilization</a></nav>
<?php if($data['legacy']):?><p class="report-notes">Original <?=fre($data['legacy']['status'])?> reconciliation #<?=fre($data['legacy']['id'])?> remains preserved. Historical signed adjustment lines are not reinterpreted as typed sources.</p><?php endif;?>
<section id="reconciliation"><h2>Account-wide reconciliation</h2><p><?=fre($data['closure_blocker'])?></p>
<?php if($draft):?><div class="context"><strong>Version <?=fre($version)?> · <?=fre($draft['status'])?></strong><span>Adjusted bank <?=fre(moneyString((int)$draft['totals']['adjusted_bank_cents']))?></span><span>Adjusted books <?=fre(moneyString((int)$draft['totals']['adjusted_book_cents']))?></span><span>Difference <?=fre(moneyString((int)$draft['totals']['difference_cents']))?></span></div><?php endif;?>
<?php if($opening):?><p>Verified account opening <?=fre(moneyString((int)$opening['opening_cents']))?> at <?=fre($opening['start_date'])?> · Maintaining balance <?=fre(moneyString((int)$opening['maintaining_cents']))?>. Books are calculated from this opening and the complete account source history.</p><?php endif;?>
<?php if($writable&&$opening&&!$isClosed&&!$legacyClosed):?><form id="finance-draft" data-finance-route="finance.review.draft" data-csrf="<?=fre($csrf)?>" data-request-key="<?=fre(bin2hex(random_bytes(16)))?>"><?php frhidden($org,$bank,$period,$version);?>
<div class="filters"><label>Actual statement closing balance<input name="statement_balance" inputmode="decimal" required value="<?=fre($draft?moneyString((int)$draft['statement_cents']):'')?>"></label><label>Statement evidence reference<input name="statement_evidence" maxlength="255" required value="<?=fre($draft['statement_evidence']??'')?>"></label><label>Revision / closure reason<input name="reason" maxlength="500" minlength="8" required></label></div>
<details open><summary>Verified adjustments to include</summary><p>All book adjustments and outstanding checks are required. Choose only supported bank-side adjustments unresolved at this cutoff.</p><div class="finance-source-list"><?php foreach($data['sources']??[] as $s):?><label><input type="checkbox" name="source_ids[]" value="<?=fre($s['id'])?>" <?=!empty($s['resolved_at_cutoff'])?'disabled':(in_array($s['id'],$selectedSources)?'checked':'')?>>#<?=fre($s['id'])?> · <?=fre($s['effective_date'].' · '.$s['kind'].' · '.$s['amount'].' · '.$s['evidence_reference'].(!empty($s['resolved_at_cutoff'])?' · RESOLVED':''))?></label><?php endforeach;?><?php foreach($checks as $c):?><label><input type="checkbox" name="check_ids[]" value="<?=fre($c['id'])?>" <?=in_array($c['id'],$selectedChecks)?'checked':''?>>Outstanding check <?=fre($c['check_number'].' / '.$c['dv_number'].' · '.$c['amount'].' · '.$c['stage_at_end'])?></label><?php endforeach;?></div></details>
<div class="action-row noprint"><button type="submit">Save verified draft</button><button type="submit" data-finance-action="finance.review.close">Close balanced complete account</button></div></form><?php elseif($writable&&($isClosed||$legacyClosed)):?><form class="filters noprint" data-finance-route="finance.review.reopen" data-csrf="<?=fre($csrf)?>" data-request-key="<?=fre(bin2hex(random_bytes(16)))?>"><?php frhidden($org,$bank,$period,$version);?><label>Audited reopening reason<input name="reason" required minlength="12" maxlength="500"></label><button>Reopen after dependency checks</button></form><?php endif;?></section>
<section id="verified-sources"><h2>Verified account sources</h2>
<?php if($writable&&!$opening):?><details open><summary>Establish verified opening and maintaining balance</summary><p>Use independently verified opening books and statement evidence. The start must precede every recorded account credit and check.</p><form class="filters noprint" data-finance-route="finance.review.opening" data-csrf="<?=fre($csrf)?>" data-request-key="<?=fre(bin2hex(random_bytes(16)))?>"><?php frhidden($org,$bank,$period);?><label>Opening date<input type="date" name="start_date" required></label><label>Opening balance<input name="opening_balance" inputmode="decimal" required></label><label>Required maintaining balance<input name="maintaining_balance" inputmode="decimal" required></label><label>Statement evidence<input name="statement_evidence" maxlength="255" required></label><label>Book evidence<input name="book_evidence" maxlength="255" required></label><label>Independent verification reference<input name="verification_reference" maxlength="255" required></label><label>Reason<input name="reason" maxlength="500" required></label><button>Record verified opening</button></form></details><?php endif;?>
<?php if($writable):?><details><summary>Record supported deposit, charge, interest or correction source</summary><p>Use exact documentary references. Deposits must match a recorded fund credit; book corrections must match an approved cash accounting line. These records do not create DV payments or fund credits.</p><form class="filters noprint" data-finance-route="finance.review.source" data-csrf="<?=fre($csrf)?>" data-request-key="<?=fre(bin2hex(random_bytes(16)))?>"><?php frhidden($org,$bank,$period);?><label>Source kind<select name="kind"><?php foreach(['DEPOSIT_IN_TRANSIT','BANK_ERROR_ADD','BANK_ERROR_SUBTRACT','BANK_CHARGE','BANK_INTEREST','BOOK_ERROR_ADD','BOOK_ERROR_SUBTRACT','SOURCE_RESOLVED'] as $k):?><option><?=fre($k)?></option><?php endforeach;?></select></label><label>Effective date<input type="date" name="effective_date" required></label><label>Exact amount<input name="amount" inputmode="decimal" required></label><label>Unique source reference<input name="source_reference" maxlength="100" required></label><label>Source evidence<input name="evidence_reference" maxlength="255" required></label><label>Statement reference<input name="statement_reference" maxlength="255" required></label><label>Independent verification reference<input name="verification_reference" maxlength="255" required></label><label>Deposit fund event ID, when applicable<input type="number" min="1" name="fund_event_id"></label><label>Approved cash accounting line ID, for book correction<input type="number" min="1" name="accounting_line_id"></label><label>Original bank-side source ID, when resolving<input type="number" min="1" name="source_id"></label><label>Resolution / revision reason<input name="reason" maxlength="500"></label><button>Record verified source</button></form></details><?php endif;?></section>
<section id="snapshots"><h2>Preserved historical reports</h2><p>Closing preserves report inputs and effective signatories. Later reconstructions are labeled as such; historical reconstruction is never represented as genuine evidence captured at the original month-end.</p>
