<?php if($snapshot):$basis=$snapshot['body']['basis'];$savedFunds=$snapshot['body']['payload']['report_sources']['funds']??[];?><div class="context"><strong>Snapshot #<?=fre($snapshot['snapshot_id'])?> · <?=fre($basis['provenance'])?></strong><span>Captured <?=fre($basis['captured_at'])?></span><span><?=($basis['complete']??false)?'Preserved close inputs':'Incomplete historical evidence'?></span></div><p>Stored digest verified: <code><?=fre($snapshot['sha256'])?></code></p><?php foreach($basis['gaps']??[] as $gap):?><p class="report-notes"><?=fre($gap)?></p><?php endforeach;?>
<?php if($savedFunds):?><div class="finance-table-scroll"><table><thead><tr><th>Preserved fund</th><th>Generate report directly from saved source inputs</th></tr></thead><tbody><?php foreach($savedFunds as $f):?><tr><td><?=fre($f['source_code'].' / '.$f['name'])?></td><td><?php foreach(['A80','S1','A35','A40','A43','A67'] as $code):?><a href="cash-fund-reports.php?<?=fre(http_build_query(['organization_id'=>$org,'snapshot_id'=>$snapshot['snapshot_id'],'fund_id'=>$f['id'],'bank_account_id'=>$bank,'period'=>$period,'report'=>$code]))?>" target="_blank" rel="noopener"><?=fre($code)?></a> <?php endforeach;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><details><summary>Preserved raw source evidence</summary><pre><?=fre(json_encode($snapshot['body'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre></details><?php endif;?></section>
